/**
 * Deploy-time check for customer OIDC audiences. The backend repeats this
 * check with the same rules before it stores a manifest.
 */
export const OIDC_AUDIENCE_MAX_COUNT = 8;
export const OIDC_AUDIENCE_MAX_LENGTH = 512;
/** Always reserved, including when a deployment has no session audience. */
export const CURSOR_EXCHANGE_AUDIENCE = "https://cursor.com/agent-sdk";
export const OIDC_ISSUER_ORIGIN = "https://api.cursor.com";
export const OIDC_MCP_ALLOWLIST_AUDIENCE = "https://api.cursor.com/mcp-allowlist";
/** Reserved values the CLI can reject without reading backend config. */
export const CLI_RESERVED_OIDC_AUDIENCES = [
    CURSOR_EXCHANGE_AUDIENCE,
    OIDC_ISSUER_ORIGIN,
    OIDC_MCP_ALLOWLIST_AUDIENCE,
];
const PRINTABLE_ASCII = /^[!-~]+$/;
export function validateOidcAudiences(list, reserved) {
    if (list.length > OIDC_AUDIENCE_MAX_COUNT) {
        return { ok: false, reason: "too_many" };
    }
    const reservedSet = new Set(reserved);
    for (const entry of list) {
        if (entry.length < 1 ||
            entry.length > OIDC_AUDIENCE_MAX_LENGTH ||
            !PRINTABLE_ASCII.test(entry) ||
            entry.includes("*")) {
            return { ok: false, reason: "malformed" };
        }
        if (reservedSet.has(entry)) {
            return { ok: false, reason: "reserved" };
        }
    }
    return { ok: true, audiences: list };
}
